<script setup>
import { router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminDataTable from '../../Components/AdminDataTable.vue';
import Modal from '../../Components/Modal.vue';
import ActionIconButton from '../../Components/ActionIconButton.vue';
import SearchSelect from '../../Components/SearchSelect.vue';
import PortalLayout from '../../Layouts/PortalLayout.vue';
import SectionTitle from '../../Components/SectionTitle.vue';
import { formatDate, formatDateTime } from '../../lib/date';

const props = defineProps({ mode: String, venues: { type: [Array, Object], default: () => [] }, sports: { type: Array, default: () => [] }, events: { type: Array, default: () => [] }, matches: { type: Array, default: () => [] }, agendas: Object, agendaStats: { type: Object, default: () => ({}) }, filters: Object });
const venueId = ref(null);
const agendaId = ref(null);
const venueModal = ref(false);
const agendaModal = ref(false);
const selectedAgenda = ref(null);
const deleteAgendaTarget = ref(null);
const deletingAgenda = ref(false);
const unscheduleTarget = ref(null);
const activeTab = ref('agenda');
const scheduleSearch = ref('');
const collapsedDates = ref(new Set());
const venueOptions = computed(() => Array.isArray(props.venues) ? props.venues : props.venues.data || []);
const activeVenueCount = computed(() => venueOptions.value.filter((item) => item.is_active).length);
const venue = useForm({ code: '', name: '', address: '', city: '', facilities: '', map_url: '', contact_name: '', contact_phone: '', latitude: '', longitude: '', is_active: true });
const agenda = useForm({ date: '', title: '', type: 'sport', sport_id: '', tournament_event_id: '', venue_id: '', start_time: '', end_time: '', time_note: '', description: '', change_note: '' });
const saveVenue = () => venue.submit(venueId.value ? 'put' : 'post', venueId.value ? `/admin/venues/${venueId.value}` : '/admin/venues', { preserveScroll: true, onSuccess: () => { venue.reset(); venueId.value = null; venueModal.value = false; } });
const saveAgenda = () => agenda.submit(agendaId.value ? 'put' : 'post', agendaId.value ? `/admin/agendas/${agendaId.value}` : '/admin/agendas', { preserveScroll: true, onSuccess: () => { agenda.reset(); agendaId.value = null; agendaModal.value = false; } });
const openVenue = (item = null) => { venue.reset(); venue.clearErrors(); venueId.value = item?.id || null; if (item) Object.keys(venue.data()).forEach((key) => { venue[key] = item[key] ?? (key === 'is_active' ? false : ''); }); venueModal.value = true; };
const deleteVenue = (item) => { if (confirm(`Hapus venue ${item.name}?`)) router.delete(`/admin/venues/${item.id}`, { preserveScroll: true }); };
const mapsUrl = (item) => item.map_url || (item.latitude && item.longitude ? `https://www.google.com/maps/search/?api=1&query=${item.latitude},${item.longitude}` : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([item.name, item.address, item.city].filter(Boolean).join(', '))}`);
const showVenue = (item) => window.open(mapsUrl(item), '_blank', 'noopener');
const toggleVenue = (item) => router.put(`/admin/venues/${item.id}`, { ...item, is_active: !item.is_active }, { preserveScroll: true });
const openAgenda = (item = null) => { agenda.reset(); agenda.clearErrors(); agendaId.value = item?.id || null; if (item) { Object.keys(agenda.data()).forEach((key) => { agenda[key] = item[key] ?? ''; }); agenda.date = item.date?.slice(0, 10) || ''; agenda.start_time = item.start_time?.slice(0, 5) || ''; agenda.end_time = item.end_time?.slice(0, 5) || ''; } agendaModal.value = true; };
const publish = (id) => router.post(`/admin/agendas/${id}/publish`, {}, { preserveScroll: true });
const toggleAgenda = (item) => router.post(`/admin/agendas/${item.id}/toggle-status`, {}, { preserveScroll: true });
const agendaStatusLabel = (item) => item.status === 'published' ? 'Aktif' : item.status === 'cancelled' ? 'Nonaktif' : 'Draft';
const formatGroupDate = (value) => new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(value)).replace('.', '');
const groupAgendas = (rows) => Object.values(rows.reduce((groups, item) => { const key = item.date?.slice(0, 10) || 'tanpa-tanggal'; groups[key] ||= { key, label: item.date ? formatGroupDate(item.date) : 'Tanggal belum ditetapkan', agendas: [], published: 0, venues: new Set() }; groups[key].agendas.push(item); groups[key].published += item.status === 'published' ? 1 : 0; if (item.venue_name) groups[key].venues.add(item.venue_name); return groups; }, {}));
const isDateExpanded = (key) => !collapsedDates.value.has(key);
const toggleDate = (key) => { const collapsed = new Set(collapsedDates.value); collapsed.has(key) ? collapsed.delete(key) : collapsed.add(key); collapsedDates.value = collapsed; };
const allDatesExpanded = (rows) => groupAgendas(rows).every((group) => isDateExpanded(group.key));
const toggleAllDates = (rows) => { collapsedDates.value = allDatesExpanded(rows) ? new Set(groupAgendas(rows).map((group) => group.key)) : new Set(); };
const editSelectedAgenda = () => { const item = selectedAgenda.value; selectedAgenda.value = null; openAgenda(item); };
const removeAgenda = () => { if (!deleteAgendaTarget.value) return; deletingAgenda.value = true; router.delete(`/admin/agendas/${deleteAgendaTarget.value.id}`, { preserveScroll: true, onSuccess: () => { deleteAgendaTarget.value = null; }, onFinish: () => { deletingAgenda.value = false; } }); };
const schedule = useForm({ match_id: '', event_agenda_id: '' });
const unschedule = useForm({ reason: '' });
const saveSchedule = () => schedule.post(`/admin/matches/${schedule.match_id}/schedule`, { preserveScroll: true, onSuccess: () => schedule.reset() });
const openUnschedule = (match) => { unschedule.reset(); unschedule.clearErrors(); unscheduleTarget.value = match; };
const cancelSchedule = () => unschedule.post(`/admin/matches/${unscheduleTarget.value.id}/unschedule`, { preserveScroll: true, onSuccess: () => { unscheduleTarget.value = null; unschedule.reset(); } });
const typeLabel = { sport: 'Pertandingan', exhibition: 'Eksibisi', official: 'Acara Resmi' };
const formatTimeRange = (item) => [item.start_time?.slice(0, 5), item.end_time?.slice(0, 5)].filter(Boolean).join('–') || 'Waktu belum ditetapkan';
const selectedMatch = computed(() => props.matches.find((item) => Number(item.id) === Number(schedule.match_id)));
const scheduleAgendaOptions = computed(() => props.agendas?.data?.filter((item) => item.status === 'published' && (!selectedMatch.value || ((!item.tournament_event_id || item.tournament_event_id === selectedMatch.value.tournament_event_id) && (!item.sport_id || item.sport_id === selectedMatch.value.tournament_event.sport_id)))) || []);
const matchOptions = computed(() => props.matches.filter((item) => !item.event_agenda_id).map((item) => ({ value: item.id, label: item.code, meta: item.tournament_event.name })));
const agendaOptions = computed(() => scheduleAgendaOptions.value.map((item) => ({ value: item.id, label: item.title, meta: `${formatDate(item.date)} · ${item.venue_name}` })));
const selectMatch = (value) => { schedule.match_id = value; schedule.event_agenda_id = ''; };
const filteredMatches = computed(() => { const search = scheduleSearch.value.trim().toLowerCase(); return props.matches.filter((item) => !search || [item.code, item.tournament_event?.name, item.venue?.name, item.event_agenda?.title].some((value) => value?.toLowerCase().includes(search))); });
</script>

<template>
  <PortalLayout portal="admin">
    <div class="page-head"><SectionTitle :eyebrow="mode === 'venues' ? 'Master Data' : 'Operasional'" :title="mode === 'venues' ? 'Master Venue' : 'Agenda & Jadwal'" /></div>
    <section v-if="mode === 'agendas'" class="overview-card operations-overview"><div><span>Kendali Operasional</span><h2>Susun agenda, lalu tempatkan pertandingan pada jadwal yang tepat.</h2><p>Agenda mengatur blok kegiatan. Jadwal menghubungkan pertandingan dengan agenda, venue, dan waktu pelaksanaan.</p></div><dl><div><dt>Total Agenda</dt><dd>{{ agendaStats.total || 0 }}</dd></div><div><dt>Terpublikasi</dt><dd>{{ agendaStats.published || 0 }}</dd></div><div><dt>Terjadwal</dt><dd>{{ agendaStats.scheduled_matches || 0 }}</dd></div></dl></section>
    <nav v-if="mode === 'agendas'" class="operation-tabs" aria-label="Agenda dan jadwal"><button type="button" :class="{ active: activeTab === 'agenda' }" @click="activeTab = 'agenda'"><span>01</span><b>Agenda</b><small>Kelola blok kegiatan</small></button><button type="button" :class="{ active: activeTab === 'schedule' }" @click="activeTab = 'schedule'"><span>02</span><b>Jadwal</b><small>Tempatkan pertandingan</small></button></nav>
    <section v-if="mode === 'venues'" class="overview-card"><div><span>Direktori Lokasi</span><h2>Kelola lokasi resmi untuk seluruh agenda lomba.</h2><p>Identitas, alamat, koordinat, kontak, dan fasilitas venue tersimpan dalam satu master.</p></div><dl><div><dt>Total Venue</dt><dd>{{ venues.total }}</dd></div><div><dt>Aktif Tampil</dt><dd>{{ activeVenueCount }}</dd></div><div><dt>Data Tampil</dt><dd>{{ venueOptions.length }}</dd></div></dl></section>
    <div v-if="mode === 'venues'" class="venue-heading"><div><b>Daftar Master Venue</b><span>Tambah venue terlebih dahulu, lalu gunakan filter pada tabel.</span></div><button @click="openVenue()">Tambah Venue</button></div>
    <AdminDataTable v-if="mode === 'venues'" :paginator="venues" :filters="filters" item-label="venue" search-placeholder="Cari nama, kode, kota, atau alamat…" :filter-options="[{ value: 'active', label: 'Aktif' }, { value: 'inactive', label: 'Nonaktif' }]">
      <template #default="{ rows }"><table><thead><tr><th>Venue</th><th>Lokasi</th><th>Koordinat</th><th>Agenda</th><th>Status</th><th style="text-align:right">Aksi</th></tr></thead><tbody>
        <tr v-for="item in rows" :key="item.id"><td><div class="primary"><strong>{{ item.name }}</strong><small>{{ item.code }}</small></div></td><td><div class="primary"><strong>{{ item.city || '—' }}</strong><small>{{ item.address || 'Alamat belum diisi' }}</small></div></td><td><a class="map-link" :href="mapsUrl(item)" target="_blank" rel="noopener">Buka Google Maps ↗</a><small v-if="item.latitude && item.longitude">{{ item.latitude }}, {{ item.longitude }}</small></td><td>{{ item.agendas_count }}</td><td><span :class="['badge', item.is_active ? 'published' : 'draft']">{{ item.is_active ? 'Aktif' : 'Nonaktif' }}</span></td><td><div class="row-actions"><ActionIconButton icon="show" label="Lihat lokasi" @click="showVenue(item)" /><ActionIconButton icon="edit" label="Edit venue" @click="openVenue(item)" /><ActionIconButton icon="power" :label="item.is_active ? 'Nonaktifkan venue' : 'Aktifkan venue'" :tone="item.is_active ? 'inactive' : 'active'" @click="toggleVenue(item)" /><ActionIconButton icon="delete" label="Hapus venue" tone="danger" :disabled="item.is_active || item.agendas_count > 0" @click="deleteVenue(item)" /></div></td></tr>
        <tr v-if="!rows.length"><td colspan="6" class="empty">Belum ada venue sesuai pencarian.</td></tr>
      </tbody></table></template>
    </AdminDataTable>
    <Modal :open="venueModal" :title="venueId ? 'Edit Venue' : 'Tambah Venue'" theme="light" @close="venueModal = false">
      <form class="modal-form" @submit.prevent="saveVenue"><div class="fields">
        <section class="form-section wide"><header><span>01</span><div><strong>Identitas Venue</strong><small>Kode dan nama menjadi referensi pada agenda serta jadwal pertandingan.</small></div></header><div class="section-fields"><label>Kode Venue<input v-model="venue.code" required /></label><label>Nama Venue<input v-model="venue.name" required /></label><label>Kota<input v-model="venue.city" /></label><label class="check"><input v-model="venue.is_active" type="checkbox" /> Venue aktif</label></div></section>
        <section class="form-section wide location-section"><header><span>02</span><div><strong>Lokasi & Koordinat</strong><small>Lengkapi alamat dan titik peta agar venue mudah ditemukan.</small></div></header><div class="section-fields"><label class="wide">Alamat<textarea v-model="venue.address" /></label><label>URL Google Maps<input v-model="venue.map_url" type="url" placeholder="https://maps.google.com/…" /></label><span></span><label>Latitude<input v-model="venue.latitude" type="number" min="-90" max="90" step="0.0000001" placeholder="-1.2379270" /></label><label>Longitude<input v-model="venue.longitude" type="number" min="-180" max="180" step="0.0000001" placeholder="116.8528520" /></label></div></section>
        <section class="form-section wide"><header><span>03</span><div><strong>Kontak & Fasilitas</strong><small>Informasi operasional yang dibutuhkan peserta dan panitia.</small></div></header><div class="section-fields"><label>Nama Kontak<input v-model="venue.contact_name" /></label><label>Telepon<input v-model="venue.contact_phone" /></label><label class="wide">Fasilitas<textarea v-model="venue.facilities" /></label></div></section>
        <p v-for="message in venue.errors" :key="message" class="error wide">{{ message }}</p>
      </div><footer class="modal-actions"><button type="button" class="modal-action secondary" :disabled="venue.processing" @click="venueModal = false">Batal</button><button type="submit" class="modal-action primary" :disabled="venue.processing">{{ venue.processing ? 'Menyimpan…' : 'Simpan Venue' }}</button></footer></form>
    </Modal>
    <section v-if="mode === 'agendas' && activeTab === 'agenda'" class="tab-panel"><div class="panel-heading"><div><span>Daftar Agenda</span><h3>Blok kegiatan resmi</h3><p>Atur tanggal, rentang waktu, venue, cabor, dan status publikasi.</p></div><button type="button" @click="openAgenda()">Tambah Agenda</button></div>
    <AdminDataTable :paginator="agendas" :filters="filters" item-label="agenda" search-placeholder="Cari agenda, cabor, atau venue…" :filter-options="[{ value: 'published', label: 'Aktif' }, { value: 'cancelled', label: 'Nonaktif' }, { value: 'draft', label: 'Draft' }]">
      <template #toolbar-actions="{ rows }"><button type="button" class="toggle-all" @click="toggleAllDates(rows)"><span :class="['tree-chevron', { open: allDatesExpanded(rows) }]" aria-hidden="true"></span>{{ allDatesExpanded(rows) ? 'Tutup Semua' : 'Buka Semua' }}</button></template>
      <template #default="{ rows }"><table><thead><tr><th>Agenda</th><th>Waktu</th><th>Venue</th><th>Tipe</th><th>Status</th><th class="actions-heading">Aksi</th></tr></thead><tbody>
        <template v-for="group in groupAgendas(rows)" :key="group.key"><tr class="date-row"><td colspan="6"><button type="button" class="date-summary" :aria-expanded="isDateExpanded(group.key)" @click="toggleDate(group.key)"><span class="date-mark">{{ group.agendas.length }}</span><div><strong>{{ group.label }}</strong><small>{{ group.agendas.length }} agenda · {{ group.venues.size }} venue</small></div><dl><div><dt>Terpublikasi</dt><dd>{{ group.published }}</dd></div><div><dt>Draft</dt><dd>{{ group.agendas.length - group.published }}</dd></div></dl><span :class="['tree-chevron', { open: isDateExpanded(group.key) }]" aria-hidden="true"></span></button></td></tr>
        <tr v-for="row in group.agendas" v-show="isDateExpanded(group.key)" :key="row.id" class="agenda-row"><td><div class="agenda-identity"><span class="tree-line"></span><div class="primary"><strong>{{ row.title }}</strong><small>{{ row.sport_name || 'Agenda Umum' }}</small></div></div></td><td><div class="time-cell"><strong>{{ formatTimeRange(row) }}</strong><small>{{ row.time_note || 'Tanpa catatan waktu' }}</small></div></td><td>{{ row.venue_name }}</td><td>{{ typeLabel[row.type] }}</td><td><span :class="['badge', row.status === 'published' ? 'published' : 'draft']">{{ agendaStatusLabel(row) }}</span></td><td><div class="row-actions"><ActionIconButton icon="show" label="Lihat agenda" @click="selectedAgenda = row" /><ActionIconButton icon="edit" :label="row.matches_count ? 'Agenda terkunci karena sudah memiliki pertandingan' : 'Edit agenda'" :disabled="row.matches_count > 0" @click="openAgenda(row)" /><ActionIconButton v-if="row.status === 'draft'" icon="publish" label="Aktifkan agenda" tone="active" @click="publish(row.id)" /><ActionIconButton v-else icon="power" :label="row.matches_count ? 'Agenda terkunci karena sudah memiliki pertandingan' : row.status === 'published' ? 'Nonaktifkan agenda' : 'Aktifkan agenda'" :tone="row.status === 'published' ? 'inactive' : 'active'" :disabled="row.matches_count > 0" @click="toggleAgenda(row)" /><ActionIconButton icon="delete" label="Hapus agenda" tone="danger" :disabled="row.status !== 'draft' || row.matches_count > 0" @click="deleteAgendaTarget = row" /></div></td></tr></template>
        <tr v-if="!rows.length"><td colspan="6" class="empty">Data agenda tidak ditemukan.</td></tr>
      </tbody></table></template></AdminDataTable></section>
    <section v-if="mode === 'agendas' && activeTab === 'schedule'" class="tab-panel schedule-panel"><form class="schedule-composer" @submit.prevent="saveSchedule"><header><div><span>Penempatan Pertandingan</span><h3>Tetapkan agenda pertandingan</h3><p>Venue dan waktu pertandingan mengikuti agenda terpilih.</p></div><strong>{{ matches.filter(item => item.event_agenda_id).length }}/{{ matches.length }} terjadwal</strong></header><div class="schedule-fields"><label>Pertandingan<SearchSelect :model-value="schedule.match_id" :options="matchOptions" placeholder="Cari pertandingan…" @update:model-value="selectMatch" /></label><label>Agenda<SearchSelect v-model="schedule.event_agenda_id" :options="agendaOptions" :disabled="!schedule.match_id" :placeholder="schedule.match_id ? 'Cari agenda yang sesuai…' : 'Pilih pertandingan dahulu'" /></label><button :disabled="schedule.processing || !schedule.match_id || !schedule.event_agenda_id">{{ schedule.processing ? 'Menyimpan…' : 'Tetapkan Jadwal' }}</button></div></form><div class="schedule-table-card"><header><div><span>Jadwal Pertandingan</span><h3>Status penempatan</h3></div><label><span>Pencarian</span><input v-model="scheduleSearch" type="search" placeholder="Cari kode, kompetisi, agenda, atau venue…" /></label></header><div class="schedule-table-scroll"><table><thead><tr><th>Pertandingan</th><th>Kompetisi</th><th>Agenda</th><th>Venue & Waktu</th><th>Status</th><th class="actions-heading">Aksi</th></tr></thead><tbody><tr v-for="item in filteredMatches" :key="item.id"><td><strong>{{ item.code }}</strong></td><td>{{ item.tournament_event.name }}</td><td>{{ item.event_agenda?.title || 'Belum ditempatkan' }}</td><td><div class="primary"><strong>{{ item.venue?.name || '—' }}</strong><small>{{ item.scheduled_at ? formatDateTime(item.scheduled_at) : 'Waktu belum ditetapkan' }}</small></div></td><td><span :class="['badge', item.event_agenda_id ? 'published' : 'draft']">{{ item.event_agenda_id ? 'Terjadwal' : 'Belum Terjadwal' }}</span></td><td><div class="row-actions"><ActionIconButton v-if="item.event_agenda_id && item.status === 'scheduled'" icon="unpublish" label="Batalkan jadwal" tone="danger" @click="openUnschedule(item)" /></div></td></tr><tr v-if="!filteredMatches.length"><td colspan="6" class="empty">Data jadwal tidak ditemukan.</td></tr></tbody></table></div></div></section>
    <Modal :open="agendaModal" :title="agendaId ? 'Edit Agenda' : 'Tambah Agenda'" theme="light" @close="agendaModal = false"><form class="modal-form agenda-modal" @submit.prevent="saveAgenda"><section class="form-section"><header><span>01</span><div><strong>Informasi Agenda</strong><small>Nama dan jenis kegiatan yang tampil pada daftar operasional.</small></div></header><div class="section-fields"><label class="wide">Judul Agenda<input v-model="agenda.title" required /></label><label>Tipe<select v-model="agenda.type"><option value="sport">Pertandingan</option><option value="exhibition">Eksibisi</option><option value="official">Acara Resmi</option></select></label><label>Cabor<select v-model="agenda.sport_id"><option value="">Tanpa cabor</option><option v-for="item in sports" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="wide">Kompetisi<select v-model="agenda.tournament_event_id"><option value="">Tanpa kompetisi</option><option v-for="item in events" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div></section><section class="form-section location-section"><header><span>02</span><div><strong>Waktu & Venue</strong><small>Venue sama tidak dapat memakai rentang waktu yang bertabrakan.</small></div></header><div class="section-fields"><label>Tanggal<input v-model="agenda.date" type="date" required /></label><label>Venue<select v-model="agenda.venue_id" required><option value="">Pilih venue</option><option v-for="item in venueOptions.filter(v => v.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Mulai<input v-model="agenda.start_time" type="time" required /></label><label>Selesai<input v-model="agenda.end_time" type="time" required /></label><label class="wide">Catatan Waktu<input v-model="agenda.time_note" placeholder="Opsional, contoh: peserta hadir 30 menit lebih awal" /></label></div></section><section v-if="agendaId" class="form-section"><header><span>03</span><div><strong>Alasan Perubahan</strong><small>Wajib diisi saat agenda yang sudah dipublikasikan diperbarui.</small></div></header><label>Catatan Perubahan<textarea v-model="agenda.change_note" placeholder="Jelaskan alasan perubahan agenda" /></label></section><p v-for="message in agenda.errors" :key="message" class="error">{{ message }}</p><footer class="modal-actions"><button type="button" class="modal-action secondary" :disabled="agenda.processing" @click="agendaModal = false">Batal</button><button type="submit" class="modal-action primary" :disabled="agenda.processing">{{ agenda.processing ? 'Menyimpan…' : 'Simpan Agenda' }}</button></footer></form></Modal>
    <Modal :open="!!selectedAgenda" title="Detail Agenda" theme="light" @close="selectedAgenda = null"><section v-if="selectedAgenda" class="agenda-detail"><header><span>{{ typeLabel[selectedAgenda.type] }}</span><h3>{{ selectedAgenda.title }}</h3><p>{{ selectedAgenda.sport_name || 'Agenda Umum' }}</p></header><dl><div><dt>Tanggal</dt><dd>{{ formatDate(selectedAgenda.date) }}</dd></div><div><dt>Waktu</dt><dd>{{ formatTimeRange(selectedAgenda) }}</dd></div><div><dt>Venue</dt><dd>{{ selectedAgenda.venue_name }}</dd></div><div><dt>Status</dt><dd>{{ agendaStatusLabel(selectedAgenda) }}</dd></div><div><dt>Catatan Waktu</dt><dd>{{ selectedAgenda.time_note || 'Tidak ada catatan' }}</dd></div><div><dt>Jumlah Pertandingan</dt><dd>{{ selectedAgenda.matches_count }}</dd></div></dl><footer class="modal-actions"><button type="button" class="modal-action secondary" @click="selectedAgenda = null">Tutup</button><button v-if="!selectedAgenda.matches_count" type="button" class="modal-action primary" @click="editSelectedAgenda">Edit Agenda</button></footer></section></Modal>
    <Modal :open="!!deleteAgendaTarget" title="Hapus Agenda" theme="light" stacked @close="deleteAgendaTarget = null"><section v-if="deleteAgendaTarget" class="delete-agenda-modal"><span aria-hidden="true">!</span><div><strong>Hapus {{ deleteAgendaTarget.title }}?</strong><p>Agenda draft akan dihapus permanen. Tindakan ini tidak dapat dibatalkan.</p></div><footer class="modal-actions"><button type="button" class="modal-action secondary" :disabled="deletingAgenda" @click="deleteAgendaTarget = null">Batal</button><button type="button" class="modal-action danger" :disabled="deletingAgenda" @click="removeAgenda">{{ deletingAgenda ? 'Menghapus…' : 'Hapus Agenda' }}</button></footer></section></Modal>
    <Modal :open="!!unscheduleTarget" title="Batalkan Jadwal Pertandingan" theme="light" stacked @close="unscheduleTarget = null"><form v-if="unscheduleTarget" class="unschedule-modal" @submit.prevent="cancelSchedule"><span aria-hidden="true">!</span><div><strong>Batalkan jadwal {{ unscheduleTarget.code }}?</strong><p>Pertandingan kembali menjadi belum terjadwal. Agenda, venue, dan waktu saat ini akan dilepas.</p></div><label>Alasan Pembatalan<textarea v-model="unschedule.reason" required minlength="5" maxlength="255" placeholder="Jelaskan kesalahan penempatan jadwal" /></label><p v-if="unschedule.errors.reason" class="error">{{ unschedule.errors.reason }}</p><footer class="modal-actions"><button type="button" class="modal-action secondary" :disabled="unschedule.processing" @click="unscheduleTarget = null">Batal</button><button type="submit" class="modal-action danger" :disabled="unschedule.processing || unschedule.reason.trim().length < 5">{{ unschedule.processing ? 'Membatalkan…' : 'Batalkan Jadwal' }}</button></footer></form></Modal>
  </PortalLayout>
